Function:
public class IsPrime {
public static boolean isPrime(int x) {
        if (x <= 1) {
            return false;
        }

        int i = 2;
        while (i <= x && x % i != 0) {
            i++;
        }
        return i == x;
    }
}

public class IsPrime {
public static boolean isPrime(int x) {
        if (x <= 1) {
            return false;
        }

        int i = 2;
        while (i <= x && x % i != 0) {
            i++;
        }
        return i == x;
    }
}

