public class GetLastPerson {
public static int getLastPerson(int n, int k) {
        if (n <= 0 || k <= 0) {
            throw new IllegalArgumentException("Input arguments should be positive");
        }
        int lastPerson = 0;
        for (int i = 2; i <= n; i++) {
            lastPerson += k;
            lastPerson %= i;
        }
        return lastPerson;
    }
}

