public class AddSafe {
public static int addSafe(int a, int b)
    {
        int r = a + b;
        if (((a ^ r) & (b ^ r)) < 0)
        {
            return (a & b) < 0 ? Integer.MIN_VALUE : Integer.MAX_VALUE;
        }
        return r;
    }
}

