Function:
public class Wrap {
public static int wrap(int value, int min, int max)
    {
        int newValue = value;
        final int step = max - min;

        if (newValue >= max)
        {
            while (newValue >= max)
            {
                newValue -= step;
            }
        }
        else if (newValue < min)
        {
            while (newValue < min)
            {
                newValue += step;
            }
        }
        return newValue;
    }
}

