Function:
public class NormalizeAngle {
public static double normalizeAngle(double angle) {
        angle %= (2 * Math.PI);
        if (angle > Math.PI)
            angle -= 2 * Math.PI;
        if (angle <= -Math.PI)
            angle += 2 * Math.PI;
        return angle;
    }
}

