Function:
public class AdjustOffset {
protected static int adjustOffset(int offset, int arrLen, int i) {
        if(i==0 & offset==0) {
            return 0;
        } else if(i==3 && offset>=arrLen-2) {
            return offset+1;
        } else {
            return offset - 1 + i;
        }
    }
}

