Function:
public class NormalizeLatitude {
public static double normalizeLatitude(double latitude) {
        double asRad = Math.toRadians(latitude);
        if (asRad > Math.PI / 2) {
            return Math.toDegrees(2 * Math.PI - asRad) % 90;
        } else if (-Math.PI / 2 > asRad) {
            return Math.toDegrees(-2 * Math.PI - asRad) % 90;
        }
        return latitude;
    }
}

