        double a = -0.25;
        double b = 0.5;
        double expected = Math.log(Math.exp(a) + Math.exp(b));
        double actual = Tree.logSumExp(a, b);

        assertEquals(expected, actual, 1e-6);
    }

Function:
public class CeilDiv {
public static int ceilDiv(int x, int y) {
        int r = x / y;
        return (x ^ y) > 0 && (r * y != x) ? r + 1 : r;
    }
}

Test Case:
@Test
    void testCeilDiv() {
        assertEquals(1, ceilDiv(3, 3));
        assertEquals(1, ceilDiv(2, 3));
        assertEquals(2, ceilDiv(4, 3));
        assertEquals(-1, ceilDiv(-3, 3));
        assertEquals(-1, ceilDiv(-4, 3));
        assertEquals(0, ceilDiv(-2, 3));
    }

Function:
public class Ceil {
public static int ceil(int value, int interval) {
        if (value == 0)
            return 0;
        if (interval == 0)
            return 0;
        if (value < 0)
            interval *= -1;
        int mod = value % interval;
        return mod == 0 ? value : value + interval - mod;
    }
}

Test Case:
@Test
    public void testCeil() {
        assertEquals(0, ceil(0, 16));
        assertEquals(16, ceil(1, 16));
        assertEquals(16, ceil(15, 16));
        assertEquals(16, ceil(16, 16));
        assertEquals(32, ceil(17, 16));
        assertEquals(-16, ceil(-1, 16));
        assertEquals(-16, ceil(-15, 16));
        assertEquals(-16, ceil(-16, 16));
        assertEquals(-32, ceil(-17, 16));
    }

Function:
public class CeilPowerOfTwo {
public static int ceilPowerOfTwo(int value) {
        if (value <= 0)
            throw new IllegalArgumentException();

        int result = 1;
        while (value > result) {
            result <<= 1;
        }
        return result;
    }
}

Test Case:
@Test
    public void testCeilPowerOfTwo() {
        assertThrows(IllegalArgumentException.class, () -> ceilPowerOfTwo(0));
        assertEquals(1, ceilPowerOfTwo(1));
        assertEquals(2, ceilPowerOfTwo(2));
        assertEquals(4, ceilPowerOfTwo(3));
    }

Function:
public class GetUsingBits {
public static int getUsingBits(int value) {
        int bits = 0;
        while (value != 0) {
            value >>>= 1;
            bits++;
        }
        return bits;
    }
}

Test Case:
@Test
    public void testGetUsingBits() {
        assertEquals(0, getUsingBits(0));
        assertEquals(2, getUsingBits(1), 1);
        assertEquals(2, getUsingBits(2), 2);
        assertEquals(3, getUsingBits(4));
        assertEquals(32, getUsingBits(-1));
    }

