public class BooleansToInt {
public static int booleansToInt(boolean [] booleans)
    {
        int intValue = 0;
        for(int i =0; i < booleans.length; i++)
        {
            if(booleans[i])
            {
                intValue += (1 << i);
            }
        }
        return intValue;
    }
}

