        assertEquals(BitUtils.countOf1InBinary(13), 3);
    }

Function:
public class BinLength {
public static int binLength(int n) {
        int len = 1;
        while (n >> len > 0) {
            len += 1;
        }
        return len;
    }
}

Test Case:
