public class AscIntArray {
public static Integer[] ascIntArray(int lo, int hi) {
    int length = hi - lo + 1;
    Integer[] arr = new Integer[length];
    for (int i = 0; i < length; i++) {
      arr[i] = i + lo;
    }
    return arr;
  }
}

