public class A {
private static byte a(char var0) {
    byte var1 = 0;
    if (var0 != 'c') {
      switch(var0) {
        case '0':
          break;
        case '1':
          return 1;
        case '2':
          return 2;
        case '3':
          return 3;
        case '4':
          return 4;
        case '5':
          return 5;
        case '6':
          return 6;
        case '7':
          return 7;
        case '8':
          return 8;
        case '9':
          return 9;
        default:
          switch(var0) {
            case 'A':
              return 10;
            case 'B':
              return 11;
            default:
              switch(var0) {
                case 'D':
                  return 13;
                case 'E':
                  return 14;
                case 'F':
                  return 15;
                default:
                  return 0;
              }
          }
      }
    } else {
      var1 = 12;
    }

    return var1;
  }
}

