public class SignSafeMod {
public static int signSafeMod(long dividend, int divisor) {
        int mod = (int) (dividend % divisor);

        if (mod < 0) {
            mod += divisor;
        }

        return mod;
    }
}

Test Case:
@Test
    public void testSignSafeMod() {
        assertEquals(1, signSafeMod(11, 2));
        assertEquals(1, signSafeMod(-11, 2));
        assertEquals(1, signSafeMod(11, -2));
        assertEquals(-3, signSafeMod(-11, -2));
    }

