Function:
public class CountRecursive {
public static int countRecursive(int coins[], int c, int sum) {

    if (sum == 0)
      return 1;
    if (sum < 0)
      return 0;
    if (c <= 0 && sum >= 1)
      return 0;

    return countRecursive(coins, c - 1, sum)
      + countRecursive(coins, c, sum - coins[c - 1]);
  }
}

