            fail();
        } catch (ArithmeticException e) {
            // expected
        }
        try {
            MathHelper.add(1, Integer.MAX_VALUE);
            fail();
        } catch (ArithmeticException e) {
            // expected
        }
        try {
            MathHelper.add(Integer.MIN_VALUE, -1);
            fail();
        } catch (ArithmeticException e) {
            // expected
        }
    }

