Function:
public class OffsetToString {
public String offsetToString(int minutes) {
		int offsetInHours = Math.abs(minutes) / 60;
		int remainderInMinutes = Math.abs(minutes) % 60;
		String offsetEncoded = Integer.toString(offsetInHours * 100 + remainderInMinutes);
		StringBuilder sb = new StringBuilder();
		sb.append(minutes >= 0 ? '+' : '-');
		sb.append("0000".substring(offsetEncoded.length()));
		sb.append(offsetEncoded);
		return sb.toString();
	}
}

Test Case:
@Test
	public void testOffsetToString() {
		assertThat(timeService.offsetToString(120)).isEqualTo("+0200");
		assertThat(timeService.offsetToString(-120)).isEqualTo("-0200");
		assertThat(timeService.offsetToString(90)).isEqualTo("+0130");
		assertThat(timeService.offsetToString(0)).isEqualTo("+0000");
	}

