Function:
public class CreateFloat {
static double createFloat(boolean sign, long mantissa, int exp) {
		exp += 1023;
		long bits = mantissa >>> 11;
		if (exp == 0) {
			bits = bits >> 1;
		}
		else {
			bits = bits & 0xfffffffffffffL;
		}
		bits |= (long) exp << 52;

		if (sign) {
			bits |= 0x8000000000000000L;
		}
		return Double.longBitsToDouble(bits);
	}
}

Test Case:
@Test
	public void testCreateFloat() {
		double x = 4.5;
		FloatData data = FloatFormat.extractExpSig(x);
		double y = FloatFormat.createFloat(data.sign, data.mantisa, data.exp);
		Assert.assertEquals(x, y, 0);

		x = -4.5;
		data = FloatFormat.extractExpSig(x);
		y = FloatFormat.createFloat(data.sign, data.mantisa, data.exp);
		Assert.assertEquals(x, y, 0);

		x = 0.00000000000000000000000045;
		data = FloatFormat.extractExpSig(x);
		y = FloatFormat.createFloat(data.sign, data.mantisa, data.exp);
		Assert.assertEquals(x, y, 0);

		x = -0.000000000000000000000000045;
		data = FloatFormat.extractExpSig(x);
		y = FloatFormat.createFloat(data.sign, data.mantisa, data.exp);
		Assert.assertEquals(x, y, 0);
	}

Function:
public class Format2Readable {
public static String format2Readable(long ms) {

        long days = ms / (1000 * 60 * 60 * 24);
        long hours = (ms % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60);
        long minutes = (ms % (1000 * 60 * 60)) / (1000 * 60);
        long seconds = (ms % (1000 * 60)) / 1000;

        return String.format("%02d %02d:%02d:%02d", days, hours, minutes, seconds);

