Function:
public class Rot {
public static float rot(int turn)
    {
        switch (turn)
        {
            case 0:
                return 0;
            case 127:
                return 10;
            case -127:
                return -10;
            case -128:  // 0x80
                return Float.NaN;
            default:
                float f = turn;
                f = f / 4.733F;
                return Math.signum(f) * f * f;
        }
    }
}

