Function:
public class PowMod {
public static int powMod(int x, int y, int m) {
		if (x < 0)
			throw new IllegalArgumentException("Negative base not supported");
		if (y < 0)
			throw new IllegalArgumentException("Modular reciprocal not supported");
		if (m <= 0)
			throw new IllegalArgumentException("Modulus must be positive");
		if (m == 1)
			return 0;

		// Exponentiation by squaring
		int z = 1;
		for (; y != 0; y >>>= 1) {
			if ((y & 1) != 0)
				z = (int)((long)z * x % m);
			x = (int)((long)x * x % m);
		}
		return z;
	}
}

Test Case:
@Test public void testPowMod() {
		assertEquals(0, Library.powMod(0, 0, 1));
		assertEquals(0, Library.powMod(1, 0, 1));
		assertEquals(0, Library.powMod(0, 1, 1));
		assertEquals(0, Library.powMod(1, 1, 1));
