Test Case:
@Test public void testGcdRandomly() {
		final int trials = 1000000;
		for (int i = 0; i < trials; i++) {
			int x = rand.nextInt() >>> 1;  // uint31
			int y = rand.nextInt() >>> 1;  // uint31
			int z = Library.gcd(x, y);
			if (x == 0)
				assertEquals(y, z);
			else if (y == 0)
				assertEquals(x, z);
			else  // x, y > 0
				assertTrue(0 < z && z <= x && z <= y && x % z == 0 && y % z == 0);
		}
	}

