@Test
    public void testReadOdf() throws IOException {
        final SpreadSheet spreadSheet = new SpreadSheet(new File("src/test/resources/formulas.ods"));
        List<Sheet> sheets = spreadSheet.getSheets();
        for (Sheet sheet : sheets) {
            for(int rowIndex = 0; rowIndex < sheet.getMaxRows(); rowIndex++) {
                for(int columnIndex = 0; columnIndex < sheet.getMaxColumns(); columnIndex++) {
                    final Range dataRange = sheet.getDataRange();
                    final Range cell = dataRange.getCell(rowIndex, columnIndex);
                    if(cell.getValue() == null) continue;

                    System.out.println("cell name: "+formatAsString(columnIndex, rowIndex));
                    System.out.println("valueType="+cell.getValue().getClass().getName());
                    final Object value = cell.getValue();
                    System.out.println("value: "+value);
                    System.out.println("Formula: "+cell.getFormula());
                }
            }
        }
    }

Function:
public class AngleWrap {
public static double angleWrap(double angle) {
        double negTauToTau = angle % (Math.PI * 2);

        if (Math.abs(negTauToTau) > Math.PI) {
            negTauToTau -= Math.copySign(Math.PI * 2, negTauToTau);
        }
        return negTauToTau;
    }
}

Test Case:
@Test
    void angleWrap() {
        // Standard cases
        assertEquals(MathUtil.angleWrap(Math.PI * 4.5), Math.PI / 2, MathUtil.EPSILON);
        assertEquals(MathUtil.angleWrap(Math.PI * 5.5), -Math.PI / 2, MathUtil.EPSILON);

        // Works for large numbers
        assertEquals(MathUtil.angleWrap(Math.PI * 1000000), 0, MathUtil.EPSILON);
    }

Function:
public class Clamp {
public static double clamp(double d) {
        return Math.min(Math.max(d, -1), 1);
    }
}

Test Case:
@Test
    void clamp() {
        // Upper and lower bounds work normally
        assertEquals(MathUtil.clamp(1.25), 1.0);
        assertEquals(MathUtil.clamp(-5.5), -1.0);

        // Works for large and infinite numbers
        assertEquals(MathUtil.clamp(Double.MAX_VALUE), 1.0);
        assertEquals(MathUtil.clamp(Double.NEGATIVE_INFINITY), -1.0);

        // Doesn't change values in range
        assertEquals(MathUtil.clamp(0.10118304), 0.10118304);
        assertEquals(MathUtil.clamp(-0.8572), -0.8572);
    }

