        assertEquals(MathUtil.deadZone(0.3, 0.2), 0.3);

        assertEquals(MathUtil.deadZone(-0.02, 0.2), 0);
        assertEquals(MathUtil.deadZone(-0.3, 0.2), -0.3);
    }

Function:
public class PowRetainingSign {
public static double powRetainingSign(double d, double power) {
        // In case d is super small, just make it zero
        if (Math.abs(d) < 1e-14) {
            return 0;
        }
        return Math.copySign(Math.pow(Math.abs(d), power), d);
    }
}

Test Case:
@Test
    void powRetainingSign() {
        assertEquals(4, MathUtil.powRetainingSign(2, 2));
        assertEquals(-4, MathUtil.powRetainingSign(-2, 2));

        double EXPECTED_1_5_POWER = Math.sqrt(Math.pow(2, 3));

        assertEquals(EXPECTED_1_5_POWER, MathUtil.powRetainingSign(2, 1.5));
        assertEquals(-EXPECTED_1_5_POWER, MathUtil.powRetainingSign(-2, 1.5));
    }

Function:
public class TenCharEpoch {
public static String tenCharEpoch(long epoch) {
        String timeSince1970 = String.valueOf(epoch);
        if(timeSince1970.length() > 10) {
            return timeSince1970.substring(0, 10);
        } else {
            return String.format("%1$10s", timeSince1970).replace(" ", "0");
        }
    }
}

