public class ToBinaryString {
public static String toBinaryString(int i) {
        int count = 1, j = i;

        if (i < 0) {
            count = 32;
        } else {
            while ((j = j >>> 1) != 0) {
                count++;
            }
        }

        char[] buffer = new char[count];
        do {
            buffer[--count] = (char) ((i & 1) + '0');
            i = i >>> 1;
        } while (count > 0);
        return new String(buffer);
    }
}

