public class GetStars {
public int getStars(int neededMoves, int minimumMoves) {

        int stars;

        if ((minimumMoves - neededMoves) >= 0) {
            stars = 3;
        } else if (((float) (minimumMoves) / neededMoves) > 0.6) {
            stars = 2;
        } else {
            stars = 1;
        }

        return stars;
    }
}

