Function:
public class Mask {
int mask(byte b, int mask) {
        switch (mask) {
        case 0:
            return (b & ~3); // 00
        case 1:
            return (b & ~3) | 1; // 10
        case 2:
            return (b & ~3) | 2; // 01
        default:
            return (b & ~3) | 3; // 11
        }
    }
}

