		for (int i = 0; i < n; i++) {
			Assert.assertArrayEquals(expecteds[i], actuals[i]);
		}

		n = 2;
		actuals = Matrix.SpiralMatrix(n);

		expecteds = new int[][]{{1,2},{4,3}};
		for (int i = 0; i < n; i++) {
			Assert.assertArrayEquals(expecteds[i], actuals[i]);
		}

		n = 3;
		actuals = Matrix.SpiralMatrix(n);

		expecteds = new int[][]{{1,2,3},{8,9,4},{7,6,5}};
		for (int i = 0; i < n; i++) {
			Assert.assertArrayEquals(expecteds[i], actuals[i]);
		}

		n = 5;
