Function:
public class NormalizeDegreeValue {
public static double normalizeDegreeValue(double value, int maxValue) {
        int range = 2 * maxValue;

        if (value > 0) {

            value = (value + maxValue - 1) % range;

            if (value < 0) {
                value += range;
            }

            return (value - maxValue + 1);
        } else {
            value = (value + maxValue) % range;

            if (value < 0) {
                value += range;
            }

            return (value - maxValue);
        }
    }
}

Test Case:
@Test
    public void testNormalizeDegreeValue() {

        double value1 = TileFactory.normalizeDegreeValue(-210, 180);
        Assert.assertEquals(150, value1, 0.00001);
        double value2 = TileFactory.normalizeDegreeValue(-91, 90);
        Assert.assertEquals(89, value2, 0.00001);

        double value3 = TileFactory.normalizeDegreeValue(210, 180);
        Assert.assertEquals(-150, value3, 0.00001);
        double value4 = TileFactory.normalizeDegreeValue(91, 90);
        Assert.assertEquals(-89, value4, 0.00001);
    }

Function:
public class CalculateExpiry {
static long calculateExpiry(long now, int maxLatency, int txCount) {
		if (now < 0) throw new IllegalArgumentException();
		if (maxLatency <= 0) throw new IllegalArgumentException();
		if (txCount < 0) throw new IllegalArgumentException();
		// The maximum round-trip time is twice the maximum latency
		long roundTrip = maxLatency * 2L;
		// The interval between transmissions is roundTrip * 2 ^ txCount
		for (int i = 0; i < txCount; i++) {
			roundTrip <<= 1;
			if (roundTrip < 0) return Long.MAX_VALUE;
		}
		// The expiry time is the current time plus the interval
		long expiry = now + roundTrip;
		return expiry < 0 ? Long.MAX_VALUE : expiry;
	}
}

Test Case:
@Test
	public void testIntervalsIncreaseExponentially() {
		long first = ExponentialBackoff.calculateExpiry(0, ONE_HOUR, 0);
		long second = ExponentialBackoff.calculateExpiry(0, ONE_HOUR, 1);
		long third = ExponentialBackoff.calculateExpiry(0, ONE_HOUR, 2);
		long fourth = ExponentialBackoff.calculateExpiry(0, ONE_HOUR, 3);
		assertEquals(third, fourth / 2);
		assertEquals(second, third / 2);
		assertEquals(first, second / 2);
	}

