Function:
public class OptimalNumOfBits {
static long optimalNumOfBits(long n, double p) {
    if (p == 0) {
      p = Double.MIN_VALUE;
    }
    return (long) (-n * Math.log(p) / (Math.log(2) * Math.log(2)));
  }
}

Test Case:
@Test
  public void testBloomNumBits() {
    assertEquals(0, Bloom1Filter.optimalNumOfBits(0, 0));
    assertEquals(1549, Bloom1Filter.optimalNumOfBits(1, 0));
    assertEquals(0, Bloom1Filter.optimalNumOfBits(0, 1));
    assertEquals(0, Bloom1Filter.optimalNumOfBits(1, 1));
    assertEquals(7, Bloom1Filter.optimalNumOfBits(1, 0.03));
    assertEquals(72, Bloom1Filter.optimalNumOfBits(10, 0.03));
    assertEquals(729, Bloom1Filter.optimalNumOfBits(100, 0.03));
    assertEquals(7298, Bloom1Filter.optimalNumOfBits(1000, 0.03));
    assertEquals(72984, Bloom1Filter.optimalNumOfBits(10000, 0.03));
    assertEquals(729844, Bloom1Filter.optimalNumOfBits(100000, 0.03));
    assertEquals(7298440, Bloom1Filter.optimalNumOfBits(1000000, 0.03));
    assertEquals(6235224, Bloom1Filter.optimalNumOfBits(1000000, 0.05));
  }

