        assertEquals(-1, ArraysUtil.reverseBitsByte((byte) 255));
        assertEquals(12, ArraysUtil.reverseBitsByte((byte) 48));
        assertEquals(125, ArraysUtil.reverseBitsByte((byte) 190));
    }

