public class GetYaw {
public double getYaw(double droneHeading, double phoneHeading) {
        double difference = phoneHeading - droneHeading;

        if (difference > 180) {
            difference = difference - 180 * 2;
        } else if (difference < -180) {
            difference = difference + 180 * 2;
        }

        return difference;
    }
}

