		assertEquals(  1.00, MathUtils.magnitude(10.0,   3.14), DELTA);
		assertEquals( 10.00, MathUtils.magnitude(10.0,  54.32), DELTA);
		assertEquals(100.00, MathUtils.magnitude(10.0, 123.45), DELTA);
	}

