Function:
public class Size2Szx {
public static int size2Szx(int blockSize) {

		if (blockSize >= 1024) {
			return 6;
		} else if (blockSize <= 16) {
			return 0;
		} else {
			int maxOneBit = Integer.highestOneBit(blockSize);
			return Integer.numberOfTrailingZeros(maxOneBit) - 4;
		}
	}
}

