Function:
public class Round {
public static long round(double v) {
		// Use Math.round to tackle the special cases of +/- Infinity and NaN
		long result = Math.round(v);
		// The only special case kicks in if the value is negative and has a
		// 0.5 part.
		if (v < 0.0 && (result - v) == 0.5) {
			return result - 1;
		}
		return result;
	}
}

Test Case:
@Test
	public void testRound() {
		assertEquals("round 0.5", 1L, MathUtil.round(0.5));
		assertEquals("round -0.5", -1L, MathUtil.round(-0.5));
		assertEquals("round 50.5", 51L, MathUtil.round(50.5));
		assertEquals("round -50.5", -51L, MathUtil.round(-50.5));
		assertEquals("round +Infinity", Long.MAX_VALUE, MathUtil.round(Double.POSITIVE_INFINITY));
		assertEquals("round -Infinity", Long.MIN_VALUE, MathUtil.round(Double.NEGATIVE_INFINITY));
		assertEquals("round NaN", 0L, MathUtil.round(Double.NaN));
	}

Function:
public class EncodedSize {
public static int encodedSize(int value) {
    if (value < 0) {
      throw new IllegalArgumentException("Cannot encode negative values");
    }
    int i = 1;
    while ((value & 0xFFFFFF80) != 0L) {
      value >>>= 7;
      i++;
    }
    return i;
  }
}

