public class MostSignificantBit {
static int mostSignificantBit(int value) {
        return 31 - Integer.numberOfLeadingZeros(value);
    }
}

Test Case:
@Test
    public void testMostSignificantBit() {
        // This test provides 100% coverage of the problem space (signed 32-bit integers)
        Assert.assertEquals(-1, AbstractSnatService.mostSignificantBit(0));
        for (int bit = 0; bit < 31; bit++) {
            for (int test = 1 << bit; test < 1 << (bit + 1); test++) {
                Assert.assertEquals(bit, AbstractSnatService.mostSignificantBit(test));
            }
        }
    }

Function:
public class MultiplyColorAlpha {
public static int multiplyColorAlpha(int color, int alpha) {
    if (alpha == 255) {
      return color;
    }
    if (alpha == 0) {
      return color & 0x00FFFFFF;
    }
    alpha = alpha + (alpha >> 7); // make it 0..256
    int colorAlpha = color >>> 24;
    int multipliedAlpha = colorAlpha * alpha >> 8;
    return (multipliedAlpha << 24) | (color & 0x00FFFFFF);
  }
}

Test Case:
@Test
  public void testMultiplyColorAlpha() {
    assertEquals(0x00123456, ColorUtil.multiplyColorAlpha(0xC0123456, 0));
    assertEquals(0x07123456, ColorUtil.multiplyColorAlpha(0xC0123456, 10));
    assertEquals(0x96123456, ColorUtil.multiplyColorAlpha(0xC0123456, 200));
    assertEquals(0xC0123456, ColorUtil.multiplyColorAlpha(0xC0123456, 255));
  }

