public class EncodeInt32 {
public static byte[] encodeInt32(int id) {

		byte[] bytes = new byte[4];
		bytes[0] = (byte)(id&0x000000ff);
		bytes[1] = (byte)((id&0x0000ff00)>>8);
		bytes[2] = (byte)((id&0x00ff0000)>>16);
		bytes[3] = (byte)((id&0xff000000)>>24);
		return bytes;
	}
}

