        assertEquals(0, paginationHelper.toIndex(0, 1, 2));
        assertEquals(0, paginationHelper.toIndex(1, 0, 2));
        assertEquals(0, paginationHelper.toIndex(-1, 1, 2));
        assertEquals(0, paginationHelper.toIndex(1, -1, 2));
        assertEquals(0, paginationHelper.toIndex(1, 1, -1));
        // impossible pages
        assertEquals(0, paginationHelper.toIndex(20, 10, 5));
        assertEquals(0, paginationHelper.toIndex(2, 10, 10));
        assertEquals(0, paginationHelper.toIndex(2, 100, 100));

        // valid
        assertEquals(2, paginationHelper.toIndex(1, 10, 2));
        assertEquals(11, paginationHelper.toIndex(2, 10, 11));
        assertEquals(276, paginationHelper.toIndex(23, 12, 1230));
    }

Function:
public class Fibonacci {
public long fibonacci(int number) {
        if (number <= 1) {
            return number;
        }
        return fibonacci(number - 1) + fibonacci(number - 2);
    }
}

Test Case:
@Test
    public void fibonacciTest() {
        //subject under test is created.
        Fibonacci fibonacci = new Fibonacci();

        //and, the helping values holder is created.
        long[] fibonaccies = new long[10];

        // method fibonacci is called
        for(int i = 0; i < 10; i++){
            fibonaccies[i] = fibonacci.fibonacci(i);
        }

        //expected result is returned.
        Assert.assertEquals(0, fibonaccies[0]);
        Assert.assertEquals(1, fibonaccies[1]);
        Assert.assertEquals(1, fibonaccies[2]);
        Assert.assertEquals(2, fibonaccies[3]);
        Assert.assertEquals(3, fibonaccies[4]);
        Assert.assertEquals(5, fibonaccies[5]);
        Assert.assertEquals(8, fibonaccies[6]);
        Assert.assertEquals(13, fibonaccies[7]);
        Assert.assertEquals(21, fibonaccies[8]);
        Assert.assertEquals(34, fibonaccies[9]);
    }

