Function:
public class Pow {
static public double pow(double base, int exponent)
	{
		if (exponent ==  0) return 1;
		if (exponent ==  1) return base;
		if (exponent == -1) return 1/base;

		boolean negative;

		if (exponent < 0)
		{
			negative = true;
			exponent = -exponent;
		}
		else
			negative = false;

		double mod = (exponent%2 == 0) ? 1 : base;
		double p = base;

		exponent /= 2;

		while (exponent > 0)
		{
			p = p * p;
			exponent /= 2;
		}

		mod *= p;
		return negative ? 1/mod : mod;
	}
}

Test Case:
@Test
	public void testPow()
	{
		int i, j;

		for (j=-5; j<5; j++)
		{
			if (j == 0) continue;

			for (i=-5; i<5; i++)
			{
				assertEquals(Math.pow( 2, i), MathUtils.pow( 2, i), 0);
				assertEquals(Math.pow(-2, i), MathUtils.pow(-2, i), 0);
			}
		}
	}

