public class NextPow2Int {
public static int nextPow2Int(int x) {
        --x;
        x |= x >>> 1;
        x |= x >>> 2;
        x |= x >>> 4;
        x |= x >>> 8;
        x |= x >>> 16;
        return ++x;
    }
}

Test Case:
@Test
    public void testNextPow2Int() {
        assertEquals(2, MathUtil.nextPow2Int(2));
        assertEquals(4, MathUtil.nextPow2Int(3));
        assertEquals(8, MathUtil.nextPow2Int(5));
    }

