Function:
public class Down {
public static long down(long num, int factor) {
        if (num < factor) {
            return 0;
        } else if (num % factor == 0) {
            return num;
        } else {
            return num / factor * factor;
        }
    }
}

Test Case:
@Test
    public void testDown() {
        int blockSize = 8 * 1024;
        // less
        Assert.assertEquals(0, Rounding.down(0, blockSize));
        Assert.assertEquals(0, Rounding.down(1, blockSize));
        Assert.assertEquals(0, Rounding.down(2, blockSize));

        // equals
        Assert.assertEquals(blockSize, Rounding.down(blockSize, blockSize));

        // multiple
        Assert.assertEquals(blockSize * 2, Rounding.down(blockSize * 2, blockSize));

        // not multiple
        Assert.assertEquals(blockSize, Rounding.down(blockSize + 3, blockSize));
    }

Function:
public class FindBestSampleSize {
static int findBestSampleSize(
            int actualWidth, int actualHeight, int desiredWidth, int desiredHeight) {
        double wr = (double) actualWidth / desiredWidth;
        double hr = (double) actualHeight / desiredHeight;
        double ratio = Math.min(wr, hr);
        float n = 1.0f;
        while ((n * 2) <= ratio) {
            n *= 2;
        }

        return (int) n;
    }
}

Test Case:
@Test public void findBestSampleSize() {
        // desired == actual == 1
        assertEquals(1, ImageRequest.findBestSampleSize(100, 150, 100, 150));

        // exactly half == 2
        assertEquals(2, ImageRequest.findBestSampleSize(280, 160, 140, 80));

        // just over half == 1
        assertEquals(1, ImageRequest.findBestSampleSize(1000, 800, 501, 401));

        // just under 1/4 == 4
        assertEquals(4, ImageRequest.findBestSampleSize(100, 200, 24, 50));
    }

