Function:
public class RepresentableDelta {
public static double representableDelta(double x,
                                            double delta) {
        return x + delta - x;
    }
}

Test Case:
@Test
    void testRepresentableDelta() {
        int nonRepresentableCount = 0;
        final double x = 100;
        final int numTrials = 10000;
        for (int i = 0; i < numTrials; i++) {
            final double originalDelta = Math.random();
            final double delta = Precision.representableDelta(x, originalDelta);
            if (delta != originalDelta) {
                ++nonRepresentableCount;
            }
        }

        Assertions.assertTrue(nonRepresentableCount / (double) numTrials > 0.9);
    }

Function:
public class Depair {
public static long[] depair(long z) {
		long t = (int) Math.floor((Math.sqrt(8 * z + 1) - 1) / 2);
		long x = t * (t + 3) / 2 - z;
		long y = z - t * (t + 1) / 2;

		return new long[]{x, y};
	}
}

