		int x = 10;
		int seed = 10;

		long pair = CantorPairing.pair(x, seed);
		long[] depair = CantorPairing.depair(pair);

		assertEquals(x, depair[0]);
		assertEquals(seed, depair[1]);
	}

Function:
public class CheckLevelRestrictionsActive {
public static boolean checkLevelRestrictionsActive(int playerLevel, int activeAmount){
		switch (activeAmount){
			case 0:
			case 1:
			case 2:
				return true;
			case 3:
			case 4:
			case 5:
				return playerLevel >= activeAmount * activeAmount - (5 - activeAmount);
			default:
				return false;
		}
	}
}

Test Case:
@Test
	public void testCheckLevelRestrictionsActive() {
		TestHelper.load();
		assertTrue(Inventory.checkLevelRestrictionsActive(1, 0));
		assertTrue(Inventory.checkLevelRestrictionsActive(1, 1));
		assertTrue(Inventory.checkLevelRestrictionsActive(1, 2));
		assertTrue(Inventory.checkLevelRestrictionsActive(8, 3));
		assertTrue(!Inventory.checkLevelRestrictionsActive(3, 3));
		assertTrue(Inventory.checkLevelRestrictionsActive(17, 4));
		assertTrue(!Inventory.checkLevelRestrictionsActive(3, 4));
		assertTrue(Inventory.checkLevelRestrictionsActive(28, 5));
		assertTrue(!Inventory.checkLevelRestrictionsActive(3, 5));
		assertTrue(!Inventory.checkLevelRestrictionsActive(3, 6));
	}

Function:
public class ToDecimal {
public static String toDecimal(long seconds, int nanoseconds)
    {
        StringBuilder sb = new StringBuilder(20)
            .append(seconds)
            .append('.');
        // 14-Mar-2016, tatu: Although we do not yet (with 2.7) trim trailing zeroes,
        //   for general case,
        if (nanoseconds == 0L) {
            // !!! TODO: 14-Mar-2016, tatu: as per [datatype-jsr310], should trim
            //     trailing zeroes
            if (seconds == 0L) {
                return "0.0";
            }

//            sb.append('0');
            sb.append("000000000");
        } else {
            StringBuilder nanoSB = new StringBuilder(9);
            nanoSB.append(nanoseconds);
            // May need to both prepend leading nanos (if value less than 0.1)
            final int nanosLen = nanoSB.length();
            int prepZeroes = 9 - nanosLen;
            while (prepZeroes > 0) {
                --prepZeroes;
                sb.append('0');
            }

            // !!! TODO: 14-Mar-2016, tatu: as per [datatype-jsr310], should trim
            //     trailing zeroes
            /*
            // AND possibly trim trailing ones
            int i = nanosLen;
            while ((i > 1) && nanoSB.charAt(i-1) == '0') {
                --i;
            }
            if (i < nanosLen) {
                nanoSB.setLength(i);
            }
            */
            sb.append(nanoSB);
        }
        return sb.toString();
    }
}

Test Case:
@Test
    public void testToDecimal01()
    {
        String decimal = DecimalUtils.toDecimal(0, 0);
        assertEquals("The returned decimal is not correct.", NO_NANOSECS_SER, decimal);

        decimal = DecimalUtils.toDecimal(15, 72);
        assertEquals("The returned decimal is not correct.", "15.000000072", decimal);

        decimal = DecimalUtils.toDecimal(19827342231L, 192837465);
        assertEquals("The returned decimal is not correct.", "19827342231.192837465", decimal);

        decimal = DecimalUtils.toDecimal(19827342231L, 0);
        assertEquals("The returned decimal is not correct.",
                "19827342231"+NO_NANOSECS_SUFFIX, decimal);

        decimal = DecimalUtils.toDecimal(19827342231L, 999888000);
        assertEquals("The returned decimal is not correct.",
                "19827342231.999888000", decimal);

        decimal = DecimalUtils.toDecimal(-22704862, 599000000);
        assertEquals("The returned decimal is not correct.",
                "-22704862.599000000", decimal);
    }

Function:
public class InterpretOrdinal {
static int interpretOrdinal(int ordinal, int numTiers) {
    if (ordinal >= 0) {
      return Math.min(ordinal, numTiers - 1);
    }
    return Math.max(numTiers + ordinal, 0);
  }
}

Test Case:
@Test
  public void interpretTier() throws Exception {
    Assert.assertEquals(0, StorageTierAssoc.interpretOrdinal(0, 1));
    Assert.assertEquals(0, StorageTierAssoc.interpretOrdinal(1, 1));
    Assert.assertEquals(0, StorageTierAssoc.interpretOrdinal(2, 1));
    Assert.assertEquals(0, StorageTierAssoc.interpretOrdinal(-1, 1));
    Assert.assertEquals(0, StorageTierAssoc.interpretOrdinal(-2, 1));
    Assert.assertEquals(0, StorageTierAssoc.interpretOrdinal(-3, 1));
    Assert.assertEquals(0, StorageTierAssoc.interpretOrdinal(Constants.FIRST_TIER, 1));
    Assert.assertEquals(0, StorageTierAssoc.interpretOrdinal(Constants.SECOND_TIER, 1));
    Assert.assertEquals(0, StorageTierAssoc.interpretOrdinal(Constants.LAST_TIER, 1));

    Assert.assertEquals(0, StorageTierAssoc.interpretOrdinal(0, 10));
    Assert.assertEquals(8, StorageTierAssoc.interpretOrdinal(8, 10));
    Assert.assertEquals(9, StorageTierAssoc.interpretOrdinal(9, 10));
    Assert.assertEquals(9, StorageTierAssoc.interpretOrdinal(10, 10));
    Assert.assertEquals(9, StorageTierAssoc.interpretOrdinal(-1, 10));
    Assert.assertEquals(1, StorageTierAssoc.interpretOrdinal(-9, 10));
    Assert.assertEquals(0, StorageTierAssoc.interpretOrdinal(-10, 10));
    Assert.assertEquals(0, StorageTierAssoc.interpretOrdinal(-11, 10));
    Assert.assertEquals(0, StorageTierAssoc.interpretOrdinal(Constants.FIRST_TIER, 10));
    Assert.assertEquals(1, StorageTierAssoc.interpretOrdinal(Constants.SECOND_TIER, 10));
    Assert.assertEquals(9, StorageTierAssoc.interpretOrdinal(Constants.LAST_TIER, 10));
  }

