Function:
public class SetMaskedBits {
public static int setMaskedBits(int wholeElement,int mask, int value) {
		int clearMask = ~mask;
	    int shift = Integer.numberOfTrailingZeros(mask);
	    value = value << shift;
	    wholeElement &= clearMask;
	    wholeElement |= (mask & value);
		return wholeElement;
  }
}

