    public void isBitSet() {
        assertTrue(BitwiseUtil.isBitSet((byte) 0b01, 0));
        assertTrue(BitwiseUtil.isBitSet((byte) 0b10, 1));

        assertFalse(BitwiseUtil.isBitSet((byte) 0b11111110, 0));
