        y = 1990;
        m = 11;
        d = 3;
        assertEquals("1990-11-03", DateUtils.toStandardDate(y, m, d));

        y = 1990;
        m = 5;
        d = 31;
        assertEquals("1990-05-31", DateUtils.toStandardDate(y, m, d));

        y = 2018;
        m = 12;
        d = 31;
        assertEquals("2018-12-31", DateUtils.toStandardDate(y, m, d));
    }

