public class DistanceRadians {
public static double distanceRadians(double start, double end) {
        double dist = end - start;

        if (dist > Math.PI)
            dist -= 2 * Math.PI;
        else if (dist <= -Math.PI)
            dist += 2 * Math.PI;

        return dist;
    }
}

Test Case:
@Test
    public void testDistanceRadians() {
        for (double a = 0; a < 2 * Math.PI; a += Angle.DEGREES_TO_RADIANS)
            for (double b = 0; b < 2 * Math.PI; b += Angle.DEGREES_TO_RADIANS) {
                double dist = Angle.distanceRadians(a, b);
                assertTrue(-Math.PI < dist && dist <= Math.PI);
                assertEquals(b, Angle.normalizeRadians(a + dist), Angle.DEGREES_TO_RADIANS / 2);
            }
    }

Function:
public class Compare {
public static int compare(double a, double b, double epsilon) {
        if (epsilon < 0)
            throw new IllegalArgumentException("epsilon < 0");

        final double delta = a - b;
        if (Math.abs(delta) <= epsilon)
            return 0;

        return (delta < 0 ? -1 : 1);
    }
}

Test Case:
@Test
    public void testCompareMin() {
        assertEquals( 0, MathUtils.compare(0.0, 0.0, Double.MIN_NORMAL));
        assertEquals( 0, MathUtils.compare(0.0, Double.MIN_NORMAL, Double.MIN_NORMAL));
        assertEquals( 0, MathUtils.compare(0.0, -Double.MIN_NORMAL, Double.MIN_NORMAL));

        assertEquals(-1, MathUtils.compare(0.0, 1.0, Double.MIN_NORMAL));
        assertEquals(-1, MathUtils.compare(-Double.MIN_NORMAL, Double.MIN_NORMAL, Double.MIN_NORMAL));
        assertEquals(+1, MathUtils.compare(0.0, -1.0, Double.MIN_NORMAL));
        assertEquals(+1, MathUtils.compare(Double.MIN_NORMAL, -Double.MIN_NORMAL, Double.MIN_NORMAL));

        assertEquals( 0, MathUtils.compare(0f, 0f, Float.MIN_NORMAL));
        assertEquals( 0, MathUtils.compare(0f, Float.MIN_NORMAL, Float.MIN_NORMAL));
        assertEquals( 0, MathUtils.compare(0f, -Float.MIN_NORMAL, Float.MIN_NORMAL));

        assertEquals(-1, MathUtils.compare(0f, 1f, Float.MIN_NORMAL));
        assertEquals(-1, MathUtils.compare(-Float.MIN_NORMAL, Float.MIN_NORMAL, Float.MIN_NORMAL));
        assertEquals(+1, MathUtils.compare(0f, -1f, Float.MIN_NORMAL));
        assertEquals(+1, MathUtils.compare(Float.MIN_NORMAL, -Float.MIN_NORMAL, Float.MIN_NORMAL));
    }

