Function:
public class IsPrime {
public static boolean isPrime(int candidate) {
        if (candidate <= 0)
            throw new IllegalArgumentException("candidate <= 0");

        if ((candidate & 1) == 0)
            return (candidate == 2);

        final int root = (int) Math.sqrt(candidate);
        for (int i = 3; i <= root; i += 2)
            if ((candidate % i) == 0)
                return false;

        return true;
    }
}

