		assertEquals(6, NumberTheory.countTrailingZeros((byte) 0b11000000));
		assertEquals(4, NumberTheory.countTrailingZeros((byte) 0b00010000));
		assertEquals(1, NumberTheory.countTrailingZeros((byte) 0b10101010));
	}

